   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="This is the city's largest residential area—the Outer District, Foden's fringe.", msg_color="", msg_size=0, talker="Merlot", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [34]={next_id=35, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Ninety percent of Foden's population lives here. Refugees, dreamers... no matter who you are, you'll find your place.", msg_color="", msg_size=0, talker="Merlot", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [35]={next_id=36, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Nana and I live here too. Wanted to invite you over, but the mission comes first. Next time!", msg_color="", msg_size=0, talker="Merlot", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Ninety percent...", msg_color="", msg_size=0, talker="Alicia", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5},{ 3, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Yep. Only ten percent get to live it up in the inner city, splurging like there's no tomorrow. Three days of their spending could match a month of our hard-earned wages!", msg_color="", msg_size=0, talker="Merlot", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5},{ 3, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="So most folks work their tails off in the city by day, crawl back here to sleep, save up, blow it all in a few wild days, then repeat.", msg_color="", msg_size=0, talker="Merlot", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5},{ 3, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Merlot spoke casually. Maybe she'd complained once, but now she'd adapted—this was just life.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5},{ 3, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="But you and Alicia were outsiders. You'd never seen a place where human stratification was so brutally stark.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5},{ 3, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Haven't you ever thought about... changing things?", msg_color="", msg_size=0, talker="Alicia", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5},{ 3, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Merlot blinked, then burst out laughing—making Alicia instantly realize she'd said something naive.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1304.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5},{ 3, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
